// Builds supabase/functions/btw-api/index.ts: core.js + server/handler.js + server/deno-entry.js
// in one file, so it can be pasted into the Supabase dashboard editor or deployed with the CLI.
// Usage: node scripts/build-function.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const read = p => fs.readFileSync(path.join(root, p), 'utf8');
const pkg = JSON.parse(read('package.json'));
const out = `// @ts-nocheck
// BTW Training — server (Supabase Edge Function "btw-api"), version ${pkg.version}.
// GENERATED by scripts/build-function.js from web/src/core.js, server/handler.js and
// server/deno-entry.js. Edit those files, not this one.
// Deploy: Supabase dashboard → Edge Functions → Deploy a new function → name it btw-api →
// paste this whole file → Deploy, then turn OFF "Verify JWT" for it. Or: supabase functions deploy btw-api

${read('web/src/core.js')}

${read('server/handler.js')}

${read('server/deno-entry.js')}
`;
const file = path.join(root, 'supabase', 'functions', 'btw-api', 'index.ts');
fs.mkdirSync(path.dirname(file), { recursive: true });
fs.writeFileSync(file, out);
console.log('wrote', path.relative(root, file), (out.length / 1024).toFixed(1) + ' KB');
